definition/trigger/issues_dispatch_wait_:
["trigger","issues_dispatch_wait_insert","issues","CREATE TRIGGER issues_dispatch_wait_insert AFTER INSERT ON issues
BEGIN
  UPDATE issues SET dispatch_wait_since = CASE WHEN EXISTS (
    SELECT 1 FROM workflow_states WHERE id = NEW.workflow_state_id AND dispatchable = 1 AND terminal = 0
  ) THEN NEW.created_at END WHERE id = NEW.id;
END"]

definition/trigger/issues_native_alias:
["trigger","issues_native_alias","issues","CREATE TRIGGER issues_native_alias AFTER INSERT ON issues WHEN NEW.project_id IS NULL
BEGIN
  SELECT CASE WHEN NEW.repository_id IS NULL THEN RAISE(ABORT, 'issue scope is required') END;
  UPDATE issues SET organization_id = (SELECT organization_id FROM projects WHERE repository_id = NEW.repository_id),
    project_id = (SELECT id FROM projects WHERE repository_id = NEW.repository_id), number = NEW.github_number WHERE id = NEW.id;
END"]

